"use client";

import { useState } from "react";
import { Card } from "@/components/ui/Card"; // Küçük harf 'card' kontrol et
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Trash2, FileText } from "lucide-react";
import TaskFormModal from "./TaskFormModal";
import { deleteTask, updateTaskContent } from "@/app/actions/task-actions";

export default function TaskListClient({ initialTasks }: { initialTasks: any[] }) {
  const [open, setOpen] = useState(false);
  const [geselecteerdItem, setGeselecteerdItem] = useState<any>(null);

  const handleUpdate = async (id: string, key: string, val: string) => {
    const updated = { ...geselecteerdItem, [key]: val };
    setGeselecteerdItem(updated);
    await updateTaskContent(id, updated);
  };

  const renderFields = (item: any) => {
    const Field = ({ label, fKey }: any) => (
      <div className="space-y-3 group mt-6">
        <label className="text-[11px] font-black text-teal-500 uppercase tracking-widest opacity-60">
          {label}
        </label>
        <Textarea
          value={item[fKey] || ""}
          onChange={(e) => handleUpdate(item.id, fKey, e.target.value)}
          className="bg-[#0b1233]/40 border-teal-500/20 focus:border-fuchsia-500/50 min-h-[120px] text-teal-50 text-lg"
        />
      </div>
    );

    switch (item.documentType) {
      case "review":
        return (
          <>
            <Field label="WAT heb jij gemaakt/geleerd?" fKey="geleerd" />
            <Field label="Wat beheers jij nog niet voldoende?" fKey="nietVoldoende" />
          </>
        );
      case "retrospective":
        return (
          <>
            <Field label="Wat ging allemaal goed?" fKey="goed" />
            <Field label="Wat kan beter?" fKey="beter" />
          </>
        );
      default:
        return <p className="text-teal-900 italic mt-10">Selecteer een template.</p>;
    }
  };

  return (
    <div className="min-h-screen bg-[#070B24] text-teal-200 py-10 px-8 flex flex-col items-center w-full">
      <TaskFormModal open={open} setOpen={setOpen} />

      <Card className="w-full max-w-7xl bg-[#0E153A]/60 backdrop-blur-2xl border border-teal-400/30 rounded-2xl shadow-2xl overflow-hidden border-t-teal-400/60">
        <div className="grid grid-cols-12 min-h-[850px]">
          
          {/* SIDEBAR */}
          <div className="col-span-3 border-r border-teal-400/10 bg-[#0b1233]/80 p-6 overflow-y-auto">
            <Button 
              onClick={() => setOpen(true)} 
              className="w-full bg-teal-400 text-[#070B24] font-black mb-8 hover:bg-teal-300 shadow-[0_0_20px_rgba(45,212,191,0.2)]"
            >
              + NIEUW DOCUMENT
            </Button>
            
            <div className="space-y-3">
              {initialTasks.map((task) => {
                let data;
                try {
                  data = JSON.parse(task.description || "{}");
                } catch {
                  data = { titel: task.title, documentType: "general" };
                }
                
                return (
                  <div
                    key={task.id}
                    onClick={() => setGeselecteerdItem({ ...data, id: task.id })}
                    className={`p-4 rounded-xl cursor-pointer border transition-all duration-300 ${geselecteerdItem?.id === task.id ? "border-teal-400 bg-teal-400/10 shadow-[0_0_15px_rgba(45,212,191,0.1)]" : "border-transparent bg-white/5 hover:bg-white/10"}`}
                  >
                    <div className="flex justify-between items-start">
                      <div className="flex flex-col gap-1 truncate pr-2">
                        <span className="text-[9px] font-black text-fuchsia-500 uppercase tracking-tighter">
                          {data.documentType || "TASK"}
                        </span>
                        <span className="font-bold text-sm text-teal-50 truncate">{task.title}</span>
                      </div>
                      <button 
                        onClick={(e) => { e.stopPropagation(); deleteTask(task.id); }}
                        className="text-teal-900 hover:text-red-500 transition-colors pt-1"
                      >
                        <Trash2 size={14} />
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* EDITOR AREA */}
          <div className="col-span-9 p-16 bg-gradient-to-br from-transparent to-teal-500/5">
            {geselecteerdItem ? (
              <div className="max-w-3xl mx-auto animate-in fade-in slide-in-from-right-10 duration-700">
                <div className="border-l-4 border-fuchsia-500 pl-6 mb-12">
                  <h1 className="text-5xl font-black text-white italic uppercase tracking-tighter leading-none">
                    {geselecteerdItem.titel}
                  </h1>
                  <p className="text-teal-500 text-[10px] font-black mt-2 tracking-[0.3em] opacity-50">
                    SPRINT {geselecteerdItem.sprint || "1"} // {geselecteerdItem.datum}
                  </p>
                </div>
                <div className="space-y-4">
                  {renderFields(geselecteerdItem)}
                </div>
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center opacity-10">
                <FileText size={120} className="mb-4" />
                <p className="text-3xl font-black uppercase tracking-[0.6em] italic">No File Selected</p>
              </div>
            )}
          </div>
        </div>
      </Card>
    </div>
  );
}