"use server";

import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";

export async function createNewTask(data: any) {
  try {
    const user = await prisma.user.findFirst();
    if (!user) return { success: false, error: "User bulunamadı" };

    await prisma.task.create({
      data: {
        title: data.titel,
        // Şemanda 'content' yok, o yüzden 'description' alanına JSON gömüyoruz
        description: JSON.stringify(data), 
        userId: user.id,
        status: "TODO",
        priority: "MEDIUM",
      },
    });

    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    console.error("Prisma Hatası:", error);
    return { success: false };
  }
}

export async function deleteTask(id: string) {
  try {
    await prisma.task.delete({ where: { id } });
    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    return { success: false };
  }
}

export async function updateTaskContent(id: string, fullData: any) {
  try {
    await prisma.task.update({
      where: { id },
      data: { description: JSON.stringify(fullData) },
    });
    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    return { success: false };
  }
}