"use client";

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { createNewTask } from "@/app/actions/task-actions";

export default function TaskFormModal({ open, setOpen }: any) {
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    
    const formData = new FormData(e.currentTarget);
    const data = {
      titel: formData.get("titel") as string,
      sprint: formData.get("sprint") as string,
      documentType: formData.get("type") as string,
      datum: new Date().toLocaleDateString("nl-NL"),
    };

    const res = await createNewTask(data);
    if (res.success) {
      setOpen(false); // Modal'ı kapatır
      (e.target as HTMLFormElement).reset(); // Formu temizler
    }
    setLoading(false);
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="bg-[#0E153A] border border-teal-400/30 text-white shadow-[0_0_50px_rgba(45,212,191,0.1)]">
        <form onSubmit={handleSubmit} className="space-y-6">
          <DialogHeader>
            <DialogTitle className="text-2xl font-black text-teal-400 italic tracking-tighter">
              NIEUW DOCUMENT
            </DialogTitle>
            <DialogDescription className="text-teal-700 text-xs uppercase font-bold">
              Selecteer een template ve start met schrijven
            </DialogDescription>
          </DialogHeader>
          
          <div className="space-y-4">
            <div className="space-y-2">
              <Label className="text-teal-500 font-bold text-[10px] uppercase">Titel</Label>
              <Input name="titel" className="bg-[#070B24] border-teal-500/20 focus:border-fuchsia-500 text-teal-100" placeholder="Bijv: Sprint 1 Review" required />
            </div>
            
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label className="text-teal-500 font-bold text-[10px] uppercase">Sprint</Label>
                <Input name="sprint" type="number" defaultValue="1" className="bg-[#070B24] border-teal-500/20 text-teal-100" />
              </div>
              <div className="space-y-2">
                <Label className="text-teal-500 font-bold text-[10px] uppercase">Template Type</Label>
                <select name="type" className="w-full h-10 px-3 bg-[#070B24] border border-teal-500/20 rounded-md text-teal-200 text-sm focus:outline-none focus:ring-1 focus:ring-fuchsia-500">
                  <option value="review">Review</option>
                  <option value="retrospective">Retrospective</option>
                  <option value="sprintplan">Sprint Plan</option>
                  <option value="daily">Daily Scrum</option>
                </select>
              </div>
            </div>
          </div>

          <DialogFooter>
            <Button 
              type="submit" 
              disabled={loading} 
              className="w-full bg-teal-400 hover:bg-teal-300 text-[#070B24] font-black py-6 rounded-xl transition-all shadow-[0_0_20px_rgba(45,212,191,0.3)]"
            >
              {loading ? "INITIALIZING..." : "GENERATE DOCUMENT"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}